const lightboxDiv=document.getElementById("lightboxwrapper"),lightboxIMG=document.getElementById("lightboximage"),lightboxCross=document.getElementById("lightboxcross"),lightboxLinks=document.querySelectorAll(".worklinkimg");let isFadeOut=!0;function cross(){console.log("Cross Pressed!"),lightboxDiv.style.opacity="0"}function lightboxhidden(){0==isFadeOut?(isFadeOut=!0,lightboxDiv.style.display="none",console.log("FadeOut")):(isFadeOut=!1,console.log("FadeIn"))}function lightboxappear(){console.log("Lightbox Pressed!"),lightboxDiv.style.display="flex",lightboxDiv.offsetHeight,lightboxDiv.style.opacity="1"}lightboxDiv.addEventListener("transitionend",lightboxhidden),lightboxCross.addEventListener("click",cross),lightboxLinks.forEach(t=>{t.addEventListener("click",function(e){e.preventDefault(),lightboxIMG.src=t.href,lightboxappear()})});